// install-attachments.js
// Adds the "attachments" feature to your EXISTING College Resource Hub project:
//   - optional PDF/photo on calendar events, assignments and announcements
//   - optional longer description on assignments and announcements
//   - click an item to open a pop-up with the text and the file
//
// HOW TO USE: save this file in your College-Resource-Hub ROOT folder (the one that contains
// "backend" and "frontend"), then run:   node install-attachments.js
//
// - Every file it replaces is BACKED UP first into a folder called "_backup_before_attachments".
// - Your backend/.env file and node_modules are never touched.
// - No new npm packages are needed.
// - Afterwards: cd backend -> npm start (restart the server if it is running)

const fs = require("fs");
const path = require("path");

// Every file, stored as base64 text so special characters can never break this script.
const FILES = {
  "backend/models/Announcement.js": "",
  "backend/models/Assignment.js": "",
  "backend/models/CalendarEvent.js": "",
  "backend/models/UploadedFile.js": "",
  "backend/server.js": "",
  "frontend/admin-dashboard.html": "",
  "frontend/css/style.css": "",
  "frontend/js/script.js": ""
};

const root = __dirname;

// Safety check: make sure this is really the project folder before writing anything.
if (!fs.existsSync(path.join(root, "backend", "server.js")) || !fs.existsSync(path.join(root, "frontend"))) {
  console.error("Stop: this does not look like the College-Resource-Hub root folder.");
  console.error("Put install-attachments.js next to the 'backend' and 'frontend' folders, then run it again.");
  process.exit(1);
}

const backupRoot = path.join(root, "_backup_before_attachments");
let written = 0, backedUp = 0;

for (const relPath of Object.keys(FILES)) {
  const target = path.join(root, relPath);
  fs.mkdirSync(path.dirname(target), { recursive: true });

  if (fs.existsSync(target)) {
    const backupPath = path.join(backupRoot, relPath);
    if (!fs.existsSync(backupPath)) { // never overwrite an earlier backup
      fs.mkdirSync(path.dirname(backupPath), { recursive: true });
      fs.copyFileSync(target, backupPath);
      backedUp++;
    }
  }

  fs.writeFileSync(target, Buffer.from(FILES[relPath], "base64"));
  console.log("  updated " + relPath);
  written++;
}

console.log("");
console.log("Done! " + written + " files written, " + backedUp + " old files backed up to _backup_before_attachments.");
console.log("");
console.log("NEXT STEPS:");
console.log("  1. cd backend");
console.log("  2. npm start   (restart it if it was already running)");
console.log("  3. open http://localhost:3000, log in as admin and add a calendar event with a photo");
console.log("  4. hard-refresh the browser (Ctrl+Shift+R) so it loads the new script.js and style.css");
